const types=['Decreto','Nomeação','Exoneração','Licitação','Veto','Proposta orçamentária','Regulamentação','Licença ambiental','Crédito suplementar','Procedimento administrativo','Outro'];
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Recife',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#today').textContent=today.split('-').reverse().join('/');$('#form').elements.date.value=today;
for(const t of types){$('#type').add(new Option(t,t));$('#filterType').add(new Option(t,t));}
let rows=[];try{rows=JSON.parse(localStorage.getItem('diario-em-pauta-v1')||'[]');if(!Array.isArray(rows))rows=[];}catch{}
function allRows(){return [...collectedRecords,...rows]}
function render(){let current=allRows().filter(r=>r.date===today);$('#count').textContent=current.length;let q=$('#search').value.toLowerCase(),source=$('#filterSource').value,type=$('#filterType').value;current=current.filter(r=>(!source||r.source===source)&&(!type||r.type===type)&&JSON.stringify(r).toLowerCase().includes(q));$('#entries').innerHTML=current.map(r=>`<article class="entry"><span class="tag">${esc(r.source)} · ${esc(r.type)} · ${esc(r.agency)}</span><h3>${esc(r.title)}</h3><p>${esc(r.summary)}</p><p><a target="_blank" rel="noopener" href="${esc(r.url)}">Documento oficial ↗</a> · ${esc(r.page)}</p><details><summary>Conferir trecho original</summary><div class="quote">${esc(r.original)}</div></details><div class="editorial"><span class="tag">Avaliação editorial · ${esc(r.potential)}</span><p>${esc(r.editorial)||'Ainda não avaliado.'}</p></div></article>`).join('')||'<div class="empty"><h3>Nenhum ato nesta seleção.</h3><p>Não confunda este estado com “nada publicado”.<br>Abra a fonte e registre atos da edição de hoje.</p><button onclick="document.querySelector(\'#add\').open=true;document.querySelector(\'#add\').scrollIntoView({behavior:\'smooth\'})">Registrar primeiro ato</button></div>';}
$('#form').onsubmit=e=>{e.preventDefault();const r=Object.fromEntries(new FormData(e.target));if(r.date!==today){$('#message').textContent='Use somente a edição de hoje. Datas anteriores não entram neste monitor.';return}const u=new URL(r.url);if(u.protocol!=='https:'||!(['natal.rn.gov.br','www.natal.rn.gov.br','www2.natal.rn.gov.br','portal.natal.rn.gov.br','deirn.sdoe.com.br','diariooficial.cepe.com.br','diariooficial.recife.pe.gov.br'].includes(u.hostname))){$('#message').textContent='Informe um link HTTPS de uma das quatro fontes oficiais do monitor.';return}if(rows.some(x=>x.date===r.date&&x.url===r.url&&x.page===r.page&&x.title===r.title)){$('#message').textContent='Este ato já foi registrado.';return}rows.push({...r,id:Date.now()});try{localStorage.setItem('diario-em-pauta-v1',JSON.stringify(rows))}catch{$('#message').textContent='Não foi possível salvar neste navegador. Exporte os registros antes de sair.';render();return}e.target.reset();e.target.elements.date.value=today;$('#message').textContent='Ato salvo neste navegador. Não é compartilhado automaticamente com o grupo.';render()};
for(const id of ['search','filterSource','filterType'])$('#'+id).addEventListener('input',render);
$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({date:today,mode:'seleção editorial e registros locais',records:allRows().filter(r=>r.date===today)},null,2)],{type:'application/json'}));a.download=`diario-em-pauta-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};render();
